CREATE OR REPLACE FUNCTION order_enqueue_customer_ordered() RETURNS trigger AS $$
BEGIN
  -- Enqueues a message of CustomerOrdered after a write to order (D80).
  INSERT INTO customer_ordered_queue (customer_id, note) VALUES (NEW.customer_id, NEW.note)
    ON CONFLICT (customer_id) WHERE state = 'ready' DO UPDATE SET note = excluded.note, due_at = excluded.due_at, attempts = 0, last_error = NULL, updated_at = now();
  RETURN NULL;
END;
$$ LANGUAGE plpgsql
